<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class GreetingService extends Service {
    public function getWall($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Domain::gate($e);Domain::publicView($e);$offset=Support::integer($in['offset']??0,0,100000);$approved=array_values(array_filter($e['greetings'],function($g){return $g['status']==='approved';}));$rows=array_slice(array_reverse($approved),$offset,30);return ['greetings'=>array_map(function($g){return array_intersect_key($g,array_flip(['id','displayName','message','at']));},$rows),'nextOffset'=>$offset+count($rows)<count($approved)?$offset+count($rows):null,'pollSeconds'=>$e['published']['wallSeconds']];}); }
    public function postSubmit($req,$res) { return $this->run($req,$res,function($in){$id=$in['eventId']??'';Store::limit($id,'greeting',5);$e=Store::load($id);Domain::gate($e);Domain::window($e,'greetings');$rev=$e['revision'];$operation=Support::text($in['operation']??'',80,true);$party='event';try{$party=Domain::capability($e,'rsvp')['reference'];}catch(Fault $f){}foreach($e['greetings'] as $g)if($g['operation']===$party.'|'.$operation)return ['status'=>$g['status']];if(count($e['greetings'])>=500)Support::fail('LIMIT','The memory wall has reached its message limit.',409);$g=['id'=>Support::id(),'operation'=>$party.'|'.$operation,'displayName'=>!empty($in['anonymous'])?'A guest':Support::text($in['displayName']??'',100,true),'message'=>Support::text($in['message']??'',1500,true),'status'=>$e['published']['moderation']?'pending':'approved','at'=>Support::now()];$e['greetings'][]=$g;Store::save($e,$rev,'guest','greeting_submit');return ['status'=>$g['status']];},true); }
    public function getModeration($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Identity::authorize($e,Identity::actor(),'moderate');return ['greetings'=>$e['greetings'],'revision'=>$e['revision']];}); }
    public function postModerate($req,$res) { return $this->run($req,$res,function($in){$r=Store::mutate($in['eventId']??'',Identity::actor(),'moderate',function(&$e)use($in){foreach($e['greetings'] as $i=>$g)if($g['id']===($in['greetingId']??'')){if(($in['status']??'')==='delete')array_splice($e['greetings'],$i,1);else $e['greetings'][$i]['status']=Support::choice($in['status']??'',['approved','rejected','pending']);return ['saved'=>true];}Support::fail('GREETING','Greeting not found.',404);},$in['revision']??null);return $r['value'];},true); }
}
